import * as fs from "node:fs";
import * as path from "node:path";
var CONFIG_RELPATH = path.join(".cascade", "config.json");
var KNOWN_STRING_KEYS = ["org_id", "workspace_id", "repo_url"];
function debugNote(message) {
  if (process.env.CASCADE_DEBUG || process.env.DEBUG) {
    console.debug(`[substrate-core:repoConfig] ${message}`);
  }
}
function validateRepoConfig(parsed, source) {
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    debugNote(`${source}: not a JSON object \u2014 ignoring`);
    return null;
  }
  const obj = parsed;
  for (const key of KNOWN_STRING_KEYS) {
    if (obj[key] !== void 0 && typeof obj[key] !== "string") {
      debugNote(`${source}: "${key}" is not a string \u2014 ignoring`);
      return null;
    }
  }
  return obj;
}
function loadRepoConfig(startDir) {
  let dir;
  try {
    dir = path.resolve(startDir);
  } catch {
    return null;
  }
  for (; ; ) {
    const candidate = path.join(dir, CONFIG_RELPATH);
    let raw = null;
    try {
      raw = fs.readFileSync(candidate, "utf8");
    } catch {
      raw = null;
    }
    if (raw !== null) {
      try {
        return validateRepoConfig(JSON.parse(raw), candidate);
      } catch {
        debugNote(`${candidate}: malformed JSON \u2014 ignoring`);
        return null;
      }
    }
    const parent = path.dirname(dir);
    if (parent === dir)
      return null;
    dir = parent;
  }
}
function writeRepoConfig(repoDir, cfg) {
  const cascadeDir = path.join(path.resolve(repoDir), ".cascade");
  const configPath = path.join(cascadeDir, "config.json");
  let existing = {};
  try {
    const parsed = JSON.parse(fs.readFileSync(configPath, "utf8"));
    if (typeof parsed === "object" && parsed !== null && !Array.isArray(parsed)) {
      existing = parsed;
    }
  } catch {
  }
  const merged = { ...existing, ...cfg };
  fs.mkdirSync(cascadeDir, { recursive: true });
  fs.writeFileSync(configPath, `${JSON.stringify(merged, null, 2)}
`, "utf8");
  return merged;
}

