// harnesses/mcp-servers/cascade-api/src/tools/session-note.ts
var name44 = "cascade_session_note";
var description44 = "Write or append this agent session's summary note (agent_sessions.summary_md); optionally append to the session's thread pad. Deliberate session-note authorship \u2014 the deterministic Stop-hook fallback only fills summary_md if the agent never wrote one.";
var schema44 = {
  session_id: external_exports.string().optional().describe("The Claude Code CLI session id; falls back to CLAUDE_SESSION_ID / CASCADE_SESSION_ID env"),
  summary_md: external_exports.string().describe("The session summary note (markdown) to write or append"),
  write_mode: external_exports.enum(["write", "append"]).optional().describe("'write' replaces the existing summary; 'append' (default) adds to it"),
  thread_pad_append: external_exports.string().optional().describe("Optional text to append to the session's thread-scoped context pad (only applies if the session is linked to a thread)")
};
async function handler44(args, auth) {
  try {
    const sessionId = args.session_id || process.env.CLAUDE_SESSION_ID || process.env.CASCADE_SESSION_ID;
    if (!sessionId) {
      return {
        content: [{
          type: "text",
          text: "Error: no session id \u2014 pass `session_id` or set CLAUDE_SESSION_ID / CASCADE_SESSION_ID in the environment."
        }],
        isError: true
      };
    }
    const { data: session, error: sessionError } = await auth.supabase.from("agent_sessions").select("id, summary_md, thread_id, org_id").eq("id", sessionId).maybeSingle();
    if (sessionError) {
      return { content: [{ type: "text", text: `Error fetching session: ${sessionError.message}` }], isError: true };
    }
    if (!session) {
      return {
        content: [{
          type: "text",
          text: JSON.stringify({
            success: false,
            session_id: sessionId,
            message: `No agent_sessions row found for session "${sessionId}" \u2014 session registration hasn't landed yet (the SessionStart hook writes it). Nothing was saved; retry once registration lands.`
          })
        }]
      };
    }
    const writeMode = args.write_mode ?? "append";
    const newSummary = writeMode === "write" ? args.summary_md : session.summary_md ? `${session.summary_md}

${args.summary_md}` : args.summary_md;
    const nowIso = (/* @__PURE__ */ new Date()).toISOString();
    const { error: updateError } = await auth.supabase.from("agent_sessions").update({ summary_md: newSummary, last_seen_at: nowIso }).eq("id", sessionId);
    if (updateError) {
      return { content: [{ type: "text", text: `Error updating session note: ${updateError.message}` }], isError: true };
    }
    log(`Session note ${writeMode === "write" ? "written" : "appended"}: ${sessionId}`);
    const written = [`agent_sessions.summary_md (${writeMode})`];
    let threadPadResult = null;
    if (args.thread_pad_append && session.thread_id) {
      const threadId = session.thread_id;
      const { data: existingPad, error: padSelectError } = await auth.supabase.from("context_pads").select("id, pad_content").eq("user_id", auth.userId).eq("scope_type", "thread").eq("scope_id", threadId).maybeSingle();
      if (padSelectError) {
        threadPadResult = `Thread pad NOT updated: ${padSelectError.message}`;
      } else if (existingPad) {
        const { error: padUpdateError } = await auth.supabase.from("context_pads").update({
          pad_content: existingPad.pad_content ? `${existingPad.pad_content}

${args.thread_pad_append}` : args.thread_pad_append,
          last_session_at: nowIso
        }).eq("id", existingPad.id);
        threadPadResult = padUpdateError ? `Thread pad NOT updated: ${padUpdateError.message}` : `appended to thread pad thread:${threadId}`;
      } else {
        const { error: padInsertError } = await auth.supabase.from("context_pads").insert({
          user_id: auth.userId,
          org_id: auth.orgId || null,
          scope_type: "thread",
          scope_id: threadId,
          mode: `thread:${threadId}`,
          pad_content: args.thread_pad_append,
          metadata: {},
          last_session_at: nowIso,
          session_count: 1
        });
        threadPadResult = padInsertError ? `Thread pad NOT created: ${padInsertError.message}` : `created thread pad thread:${threadId}`;
      }
      if (threadPadResult && !threadPadResult.startsWith("Thread pad NOT")) {
        written.push(threadPadResult);
      }
    } else if (args.thread_pad_append && !session.thread_id) {
      threadPadResult = "thread_pad_append ignored \u2014 this session has no thread_id.";
    }
    return {
      content: [{
        type: "text",
        text: JSON.stringify({
          success: true,
          session_id: sessionId,
          write_mode: writeMode,
          thread_id: session.thread_id ?? null,
          written,
          ...threadPadResult && (threadPadResult.startsWith("Thread pad NOT") || threadPadResult.startsWith("thread_pad_append ignored")) ? { thread_pad_warning: threadPadResult } : {},
          message: `Session note saved for "${sessionId}": ${written.join("; ")}.${threadPadResult && !written.includes(threadPadResult) ? ` Note: ${threadPadResult}` : ""}`
        })
      }]
    };
  } catch (err13) {
    return {
      content: [{ type: "text", text: `Error: ${err13 instanceof Error ? err13.message : String(err13)}` }],
      isError: true
    };
  }
}

// harnesses/mcp-servers/cascade-api/src/tools/get-project-overview.ts
var name45 = "cascade_get_project_overview";
