            <div style={{ fontSize: '11px', color: '#64748b', marginTop: '2px' }}>
              <span style={{ color: '#67e8f9', fontFamily: "'JetBrains Mono', monospace", fontWeight: 600 }}>{DATA.totalPackages}</span> packages
              <span style={{ margin: '0 8px', opacity: 0.3 }}>|</span>
              <span style={{ color: '#67e8f9', fontFamily: "'JetBrains Mono', monospace", fontWeight: 600 }}>{DATA.totalWorkItems}</span> work items
            </div>
