function validateNotebookBodyFull(body) {
  let candidate;
  try {
    candidate = JSON.parse(body);
  } catch (e) {
    const detail = e instanceof Error ? e.message : String(e);
    return {
      ok: false,
      reason: `invalid notebook spec: body is not valid JSON \u2014 ${detail}`,
      issues: [{ path: "(root)", message: `body is not valid JSON \u2014 ${detail}` }]
    };
  }
  const parsed = NotebookSpecSchema.safeParse(candidate);
  if (!parsed.success) {
    const issues = parsed.error.issues.map((issue2) => ({
      path: issue2.path.length > 0 ? issue2.path.join(".") : "(root)",
      message: issue2.message
    }));
    const first = issues[0];
    return {
      ok: false,
      reason: `invalid notebook spec: ${first.path} \u2014 ${first.message}`,
      issues
    };
  }
  return { ok: true };
}

