function isNotebookRenderer(renderer) {
  return renderer === "notebook";
}
function validateNotebookBody(body) {
  const result = validateNotebookBodyFull(body);
  if (result.ok) return { ok: true };
  const issueLines = result.issues.map((issue2) => `  - ${issue2.path} \u2014 ${issue2.message}`).join("\n");
  const reason = result.issues.length > 1 ? `${result.reason}
All validation issues:
${issueLines}` : result.reason;
  return { ok: false, reason };
}

