registerTool(
  "cascade_showrunner_consult",
  "Ask the Showrunner \u2014 a script-grounded specialist for one production \u2014 a scoped question about continuity, characters, or scene setups/payoffs. Returns a written judgement that cites the specific scene ids it used; it never returns the raw script text.",
  {
    productionId: external_exports.string().describe("The production's id (the daemon scopes the script lookup to this production's own org)."),
    scriptArtifactId: external_exports.string().describe("The script artifact id to consult against."),
    question: external_exports.string().describe("A specific, scoped question about the script \u2014 continuity, a character's arc, a scene's setup/payoff, and the like."),
    mode: external_exports.enum(["answer", "rewrite"]).optional().describe("rewrite runs the writing room: Screenwriter drafts, Script Doctor revises")
  },
  async (args) => {
    let result;
    try {
      result = await consultShowrunner({
        productionId: args.productionId,
        scriptArtifactId: args.scriptArtifactId,
        question: args.question,
        ...args.mode ? { mode: args.mode } : {}
      });
    } catch (err13) {
      return {
        content: [
          {
            type: "text",
            text: `Showrunner consult failed: ${err13 instanceof Error ? err13.message : String(err13)}`
          }
        ],
        isError: true
      };
    }
    if (isShowrunnerConsultRefusal(result)) {
      return {
        content: [
          {
            type: "text",
            text: `Showrunner refused (${result.error}): ${result.message}`
          }
        ],
        isError: true
      };
    }
    const parts = [result.answer];
    if (result.citedSceneIds.length > 0) {
      parts.push(`
Cited scenes: ${result.citedSceneIds.join(", ")}`);
    }
    return capResponse({ content: [{ type: "text", text: parts.join("\n") }] });
  }
);
registerTool(
  "cascade_studio_consult",
  "Ask the Studio specialist about ONE 'preset' artifact (a StudioPreset \u2014 a synth patch, amp tone or sampler chain for Arturia, Helix, Pro 3, Octatrack, Komplete, OP-1, Strymon or Logic). action 'advise' returns a written judgement that cites the specific params it relied on; 'audition' additionally renders the preset on the daemon and reports peak / RMS and the WAV path; 'search' answers a lookup across the org's presets in prose. The daemon does the reading and rendering \u2014 this tool never returns the raw preset body.",
  {
    presetArtifactId: external_exports.string().describe("The 'preset' artifact id to consult against (the daemon scopes the read to its own org)."),
    question: external_exports.string().describe("A specific question about the preset \u2014 its params, how to move it toward a sound, what a change would do."),
    action: external_exports.enum(STUDIO_CONSULT_ACTIONS).default("advise").describe("'advise' (judgement only), 'audition' (render + peak/RMS metrics + WAV), or 'search' (lookup across presets).")
  },
  async (args) => {
    let result;
    try {
      result = await consultStudio({
        presetArtifactId: args.presetArtifactId,
        question: args.question,
        action: args.action ?? "advise"
      });
    } catch (err13) {
      return {
        content: [
          {
            type: "text",
            text: `Studio consult failed: ${err13 instanceof Error ? err13.message : String(err13)}`
          }
        ],
        isError: true
      };
    }
    if (isStudioConsultRefusal(result)) {
      return {
        content: [
          {
            type: "text",
            text: `Studio refused (${result.error}): ${result.message}`
          }
        ],
        isError: true
      };
    }
    const parts = [result.answer];
    if (result.metrics) {
      parts.push(`
Metrics: peak ${result.metrics.peak} rms ${result.metrics.rms} wav ${result.metrics.wavPath}`);
    }
    if (result.citedParams.length > 0) {
      parts.push(`
Cited params: ${result.citedParams.join(", ")}`);
    }
    return capResponse({ content: [{ type: "text", text: parts.join("\n") }] });
  }
);
registerToolSearch(server, handles);
if (allowedTools) {
  log(
    `Toolset "${activeToolsetSelection.toolset}" active (${CASCADE_TOOLSET_ENV}): ${handles.size} of ${toolInventory.length} tools registered, ${toolsSkippedByToolset} skipped.`
  );
} else if (activeToolsetSelection.fellBack) {
  log(
    `${CASCADE_TOOLSET_ENV} named an unknown toolset \u2014 registered ALL ${handles.size} tools.`
  );
}
if (activeSurfaceSelection.surface) {
  log(
    `Launch surface "${activeSurfaceSelection.surface}" (${CASCADE_SURFACE_ENV}) \u2014 orientation only; tools unaffected.`
  );
}
if (isLeanMode()) {
  const core = new Set(coreToolNames());
  let disabled = 0;
  for (const [name94, handle] of handles) {
    if (!core.has(name94)) {
      handle.disable();
      disabled++;
    }
  }
  log(
    `Lean mode ON (CASCADE_MCP_TOOL_SEARCH): advertising ${core.size} core tools + cascade_tool_search; ${disabled} tools deferred (revealed on search via tools/list_changed).`
  );
}
{
  const wanted = resolveAlwaysLoad(process.env[ALWAYS_LOAD_ENV]);
  if (wanted.size > 0) {
    const marked = applyAlwaysLoad(handles, wanted);
    log(`${ALWAYS_LOAD_ENV}: loaded up front (no ToolSearch): ${marked.join(", ") || "none matched"}`);
  }
}
async function main() {
  log("Starting Cascade API MCP server...");
  try {
    await getAuth();
  } catch (err13) {
    log(
      `WARNING: Auth not available at startup: ${err13 instanceof Error ? err13.message : String(err13)}`
    );
    log("Tools will retry auth on first call.");
  }
  const transport = new StdioServerTransport();
  await server.connect(transport);
  const advertised = isLeanMode() ? coreToolNames().length + 1 : handles.size + 1;
  log(`Server connected and ready \u2014 ${advertised} tools advertised (${handles.size} registered + cascade_tool_search${isLeanMode() ? ", lean mode" : ""})`);
}
function isEntrypoint() {
  try {
    const invoked = process.argv[1];
    if (!invoked) return false;
    return realpathSync(invoked) === realpathSync(fileURLToPath2(import.meta.url));
  } catch {
    return false;
  }
}
if (isEntrypoint()) {
  main().catch((err13) => {
    log("Fatal error:", err13);
    process.exit(1);
  });
}
export {
  activeSurface,
  activeToolset,
  applyAuthDirectiveToToolResult,
  handles,
  registeredToolNames
};
